#!/bin/zsh
# Step 3: write config/local.xcconfig (git-ignored) for Xcode projects.
# Projects include it through a committed xcconfig such as Example/Overtime.xcconfig.
set -euo pipefail
source "${0:A:h}/../lib/common.sh"
ot_load
[[ -n ${OT_SDK:-} && -n ${OT_TOOLCHAIN_ID:-} ]] || ot_die "run make-sdk.sh and install-toolchain.sh first"

mkdir -p "$OT_ROOT/config"
cat > "$OT_ROOT/config/local.xcconfig" <<EOF
// Generated by scripts/make-xcconfig.sh for this machine. Do not commit.
SDKROOT = $OT_SDK
TOOLCHAINS = $OT_TOOLCHAIN_ID
ARCHS = x86_64
// Swift libraries in newer SDKs require macOS 13 or later.
MACOSX_DEPLOYMENT_TARGET = 13.0
EOF
ot_info "wrote $OT_ROOT/config/local.xcconfig"
